        osu_page_title: '✦ osu! 비트맵 컬렉션 + 총 PP 조회 ✦', visitor_lookup_title: '✦ osu! PP 조회 ✦', visitor_lookup_placeholder: 'osu! 사용자 이름 또는 ID', visitor_lookup_btn: '검색',
